       if(u<c.warn){const q=u/c.warn;ctx.fillStyle=rgba(col[2],0.25+0.3*q);ctx.beginPath();ctx.ellipse(X,Y,R*q,R*q*0.45,0,0,TAU);ctx.fill();continue;}
