    if ((x = r('spdMul')) !== 1) { p.spdMul *= x; if (p.spdPerm) p.spdPerm *= x; }
    if ((x = r('cdMul')) !== 1) { p.cdMul *= x; if (p.cdPerm) p.cdPerm *= x; }
    if ((x = r('magnetMul')) !== 1) { p.magnet *= x; if (p.magPerm) p.magPerm *= x; }
