      baseAtk:{get:()=>summonAtk(s.owner)},baseSpd:{get:()=>halfStat(s.owner.baseSpd,s.owner.spd)},
      dmgReduce:{get:()=>(s.owner.reduction||0)*BALANCE.inherit},level:{get:()=>Math.max(10,s.owner.level)},
