    const live = sistersAlive().filter(s => !(s.standT > 0)); if (!live.length) { pull = null; return; }
    const s = live.sort((a, b) => dist(a, p) - dist(b, p))[0], d = dist(s, p);
    if (!pull && d > CFG.tetherFar) { pull = { s }; emit('tether', { dex: s.dex }); sfx('surge'); }
