      for (let i = 0; i <= n; i++) { const u = i / n, x = s.x + (owner.x - s.x) * u, y = s.y - 18 + (owner.y - s.y) * u, w = Math.sin(u * Math.PI * 4 - now * 14) * 6 * Math.sin(u * Math.PI); ctx.lineTo(x + Math.cos(a) * w, y + Math.sin(a) * w); }
