      if (!s || s.dead || s.emergeT < CFG.emerge || !owner || owner !== N.Game.player || typeof onCollect !== 'function') return pu.apply(this, arguments);
      const col = Array.isArray(players) ? players.slice() : [players]; col.push(s);
