    ctx.save(); ctx.strokeStyle = spiral ? '#7dff6a' : '#9ad8ff'; ctx.lineWidth = 2.2; ctx.globalAlpha = 0.85; ctx.beginPath(); ctx.ellipse(s.x, s.y, 17, 6.5, 0, 0, TAU); ctx.stroke(); ctx.restore();
